package com.abhi.ganasuno.ui

import android.app.Activity
import android.content.Intent
import android.net.Uri
import android.text.InputType
import android.widget.EditText
import android.widget.Toast
import com.abhi.ganasuno.data.*
import com.google.android.material.dialog.MaterialAlertDialogBuilder
import java.util.concurrent.Executor

class AccountTools(private val a:Activity,private val io:Executor,private val current:()->Song?){
    private fun toast(s:String)=Toast.makeText(a,s,Toast.LENGTH_LONG).show()
    private fun choose(title:String,labels:List<String>,action:(Int)->Unit){if(labels.isEmpty()){toast("No results");return};MaterialAlertDialogBuilder(a).setTitle(title).setItems(labels.toTypedArray()){_,i->action(i)}.setNegativeButton("Close",null).show()}
    private fun message(title:String,text:String){MaterialAlertDialogBuilder(a).setTitle(title).setMessage(text).setPositiveButton("Close",null).show()}
    private fun confirm(title:String,text:String,action:()->Unit){MaterialAlertDialogBuilder(a).setTitle(title).setMessage(text).setNegativeButton("Cancel",null).setPositiveButton("Confirm"){_,_->action()}.show()}
    private fun ask(title:String,default:String="",secret:Boolean=false,done:(String)->Unit){val edit=EditText(a).apply{setSingleLine(true);setText(default);isSaveEnabled=false;if(secret)inputType=InputType.TYPE_CLASS_TEXT or InputType.TYPE_TEXT_VARIATION_PASSWORD};MaterialAlertDialogBuilder(a).setTitle(title).setView(edit).setCancelable(false).setNegativeButton("Cancel"){_,_->edit.text.clear()}.setPositiveButton("Continue"){_,_->val v=edit.text.toString().trim();edit.text.clear();done(v)}.show()}
    private fun token(done:(String)->Unit){ask("Short-lived authorized Google OAuth token",secret=true){t->if(Batch22.token(t))done(t)else toast("Invalid access token")}}
    private fun <T> task(run:()->T,done:(T)->Unit){toast("Working…");io.execute{val r=runCatching{run()};a.runOnUiThread{if(!a.isDestroyed&&!a.isFinishing)r.onSuccess(done).onFailure{toast("Request failed. Check network, authorization, quota or feed format; recheck remote state before retrying.")}}}}
    fun show(){choose("Account and blog · v27",listOf("Upload / append local playlist to private YouTube playlist","Disconnect playlist link (keep both copies)","Current song · YouTube rating","Browse my liked YouTube videos","Developer blog notifications","Import missing tracks from linked remote playlist","Post comment on current video")){when(it){0->selectPlaylist(false);1->selectPlaylist(true);2->rate();3->liked();4->blog();5->pull();6->current()?.let{comment(it.id,it.title)}?:toast("Play an online video first")}}}
    private fun selectPlaylist(detach:Boolean){val names=LibraryStore.names().filter{!detach||LibraryStore.remotePlaylist(it)!=null};choose("Choose local playlist",names){i->val name=names[i];val linked=LibraryStore.remotePlaylist(name);if(detach){confirm("Disconnect $name?","Only the local association will be removed. Neither playlist nor any track will be deleted."){LibraryStore.linkPlaylist(name,null);toast("Playlist disconnected")};return@choose};val tracks=LibraryStore.playlist(name);val ids=Batch26.eligible(tracks);if(ids.isEmpty()||ids.size>100){toast("Choose a playlist with 1–100 eligible online video IDs");return@choose};confirm("Manual append to YouTube","${ids.size} online tracks; ${tracks.size-ids.size} skipped. ${if(linked==null)"Create a private remote playlist." else "Append missing tracks to $linked."} No remote tracks will be removed or reordered. Token from your own authorized YouTube Data API client is required (not an API key or password). Google charges API quota."){token{t->task({val id=linked?:AccountCatalogue.create(t,name);if(linked==null)check(LibraryStore.linkPlaylist(name,id)){"Local playlist changed; remote playlist created"};id to AccountCatalogue.append(t,id,ids)}){(id,r)->message("Playlist sync result","Remote ID: $id\nAdded: ${r.added}\nAlready present: ${r.already}\nNot confirmed: ${r.pending}\n${r.error.orEmpty()}\nManual append only; no automatic or two-way sync.")}}}}}
    private fun rate(){val song=current();if(song==null||song.localUri.isNotBlank()||!Batch25.videoId(song.id)){toast("Play an online song first");return};token{t->task({AccountCatalogue.rating(t,song.id)}){old->val values=listOf("like","dislike","none");choose("${song.title} · current rating $old",listOf("Like","Dislike","Remove rating")){i->val v=values[i];confirm("Confirm YouTube rating","Set $v for ${song.title}? This changes your Google account rating. YouTube Music recommendations are not guaranteed."){task({AccountCatalogue.rate(t,song.id,v)}){toast("Google confirmed: $it")}}}}}}
    private fun liked(){token{t->task({AccountCatalogue.liked(t)}){rows->choose("Liked YouTube videos · up to 100",listOf("Import all into local favourites (non-destructive)")+rows.map{it.title+" · "+it.artist}){n->if(n==0){if(rows.isEmpty()){toast("No liked videos returned");return@choose};confirm("Import ${rows.size} liked videos?","Existing favourites are preserved. This is a local copy, not a live replacement of YouTube Music likes."){val added=LibraryStore.importRemoteFavorites(rows);toast("Imported $added new liked video references")}}else{val song=rows[n-1];choose(song.title,listOf("Open on YouTube","Save to local favourites")){i->if(i==0)open(Batch16.publicUrl("video",song.id))else{LibraryStore.addFavorites(listOf(song));toast("Saved locally")}}}}}}}
    private fun open(url:String){runCatching{a.startActivity(Intent(Intent.ACTION_VIEW,Uri.parse(url)))}.onFailure{toast("No browser available")}}
    private fun blog(){val p=BlogWatch.prefs(a);val url=p.getString("url",null);choose("Blog notifications · ${if(url==null)"off" else "on"}",listOf("Set HTTPS RSS / Atom feed","Check current feed now","Disable notifications")){i->when(i){0->ask("Developer RSS / Atom URL",url.orEmpty()){raw->val u=Batch26.https(raw);if(u==null){toast("Invalid HTTPS URL");return@ask};task({BlogWatch.fetch(u)}){rows->if(rows.isEmpty()){toast("No supported posts found");return@task};confirm("Enable daily blog notifications?","${rows.size} existing posts will be used as baseline. Future checks contact this feed about daily, subject to Android scheduling. Enable app notifications in Android settings if blocked."){runCatching{BlogWatch.configure(a,u);BlogWatch.deliver(a,u,rows)}.onSuccess{toast("Blog notifications scheduled")}.onFailure{toast("Scheduling failed; check settings")}}}};1->{if(url==null){toast("Set feed first");return@choose};task({BlogWatch.fetch(url)}){rows->runCatching{BlogWatch.deliver(a,url,rows)};choose("Recent posts",rows.map{it.title}){open(rows[it].link)}}};2->{BlogWatch.configure(a,null);toast("Blog notifications disabled")}}}}
    private fun pull(){val names=LibraryStore.names().filter{LibraryStore.remotePlaylist(it)!=null};choose("Import missing remote tracks",names){i->val name=names[i];val id=LibraryStore.remotePlaylist(name)?:return@choose;token{t->task({AccountCatalogue.pull(t,id)}){rows->val before=LibraryStore.playlist(name);val count=Batch27.merge(before,rows).size-before.size;confirm("Import $count missing tracks?","Adds metadata to $name without deleting local tracks, changing their order, or modifying YouTube. Private/deleted entries are excluded."){runCatching{LibraryStore.mergeRemote(name,id,rows)}.onSuccess{toast("Imported $it tracks")}.onFailure{toast("Playlist changed; import canceled")}}}}}}
    fun comment(video:String,title:String,parent:String=""){
        if(!Batch16.valid("video",video)){toast("No valid public video ID");return}
        val edit=EditText(a).apply{minLines=3;maxLines=8;isSaveEnabled=false;inputType=InputType.TYPE_CLASS_TEXT or InputType.TYPE_TEXT_FLAG_MULTI_LINE}
        MaterialAlertDialogBuilder(a).setTitle(if(parent.isBlank())"Write comment" else "Write reply").setView(edit).setNegativeButton("Cancel"){_,_->edit.text.clear()}.setPositiveButton("Review"){_,_->val text=Batch27.comment(edit.text.toString());edit.text.clear();if(text==null){toast("Enter 1–10000 characters");return@setPositiveButton};confirm("Post publicly on YouTube?","$title\n\n$text\n\nThis uses your authorized Google account. Review before confirming."){token{t->task({AccountCatalogue.postComment(t,video,text,parent)}){message("YouTube accepted the request","Comment reference: $it\nVisibility depends on YouTube moderation. Do not retry blindly if a request fails.")}}}}.show()
    }
}
